{
  "action": "question",
  "question_count": 2,
  "is_atomic": false,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximizing the number of complete products that can be assembled, minimizing total production hours used, or something else?",
    "Over what time horizon (e.g., a single period) does it apply?"
  ],
  "rationale": "The response asks for two distinct pieces of information: the specific optimization objective and the time horizon. A user could specify the objective without specifying the time horizon, or vice versa, making them semantically independent."
}

